return ['po-revision-date'=>'2025-12-12 21:00:21+0000','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','x-generator'=>'GlotPress/4.0.3','language'=>'uk_UA','project-id-version'=>'Plugins - WPForms &#8211; Easy Form Builder for WordPress &#8211; Contact Forms, Payment Forms, Surveys, &amp; More - Stable (latest release)','messages'=>['#%d (no name)'=>'#%d (без імені)','#%d (no title)'=>'#%d (без назви)','% Refunded'=>'% повернено','%1$d Total'=>'Загалом %1$d','%1$d form was successfully restored.'=>'%1$d форму успішно відновлено.' . "\0" . '%1$d форми було успішно відновлено.' . "\0" . '%1$d форм було успішно відновлено.','%1$d template was successfully duplicated.'=>'%1$d шаблон успішно продубльовано.' . "\0" . '%1$d шаблони успішно продубльовано.' . "\0" . '%1$d шаблонів успішно продубльовано.','%1$d template was successfully moved to Trash.'=>'%1$d шаблон успішно переміщено до кошика.' . "\0" . '%1$d шаблони успішно переміщено до кошика.' . "\0" . '%1$d шаблонів успішно переміщено до кошика.','%1$d template was successfully permanently deleted.'=>'%1$d шаблон успішно видалено назавжди.' . "\0" . '%1$d шаблони успішно видалено назавжди.' . "\0" . '%1$d шаблонів успішно видалено назавжди.','%1$d template was successfully restored.'=>'%1$d шаблон успішно відновлено.' . "\0" . '%1$d шаблони успішно відновлено.' . "\0" . '%1$d шаблонів успішно відновлено.','%1$s %2$s or above'=>'%1$s %2$s або вище','%1$s %2$s or below'=>'%1$s %2$s або нижче','%1$s &times; %2$d'=>'%1$s &times; %2$d','%1$s (%2$s min / %3$s max)'=>'%1$s (%2$s мін / %3$s макс)','%1$s Field %2$s'=>'%1$s Поле %2$s','%1$s Invalid email address %2$s.'=>'%1$s Недійсна електронна адреса %2$s.','%1$s These messages are displayed to the users as they fill out a form in real-time. Messages can include plain text and/or %2$sSmart Tags%3$s.'=>'%1$s Ці повідомлення відображаються під час заповнення форм у режимі реального часу. Повідомлення можуть містити простий текст та/або %2$sсмарт-теги%3$s.','%1$s addon'=>'Доповнення %1$s','%1$s at %2$s'=>'%1$s о %2$s','%1$s is not supported by AMP and is currently disabled.<br><a href="%2$s" rel="noopener noreferrer" target="_blank">Upgrade to reCAPTCHA v3</a> for full AMP support. <br><em>Please note: this message is only displayed to site administrators.</em>'=>'Сервіс %1$s не підтримує AMP і наразі відключений.<br><a href="%2$s" rel="noopener noreferrer" target="_blank">Перейдіть на використання reCAPTCHA v3</a> для повної підтримки AMP. <br><em>Зверніть увагу: це повідомлення відображається тільки для адміністраторів сайту.</em>','%1$s of %2$s max characters.'=>'%1$s із %2$s символів.','%1$s of %2$s max words.'=>'%1$s із %2$s максимальних слів.','%1$s vs %2$s'=>'%1$s проти %2$s','%d entry backed up'=>'Резервна копія %d запису' . "\0" . 'Зроблено резервну копію %d записів' . "\0" . 'Зроблено резервну копію %d записів','%d entry has been backed up'=>'Виконано резервне копіювання %d запису' . "\0" . 'Виконано резервне копіювання %d записів' . "\0" . 'Виконано резервне копіювання %d записів','%d payment was successfully moved to the Trash.'=>'%d платіж успішно переміщено до кошика.' . "\0" . '%d платежі успішно переміщено до кошика.' . "\0" . '%d платежів успішно переміщено до кошика.','%d payment was successfully permanently deleted.'=>'%d платіж остаточно видалено.' . "\0" . '%d платежі остаточно видалено.' . "\0" . '%d платежів остаточно видалено.','%d payment was successfully restored.'=>'%d платіж успішно відновлено.' . "\0" . '%d платежі успішно відновлено.' . "\0" . '%d платежів успішно відновлено.','%d tags were successfully deleted.'=>'%d позначки успішно видалено.','%s (First)'=>'%s (Ім\'я)','%s (Full)'=>'%s (ПІБ)','%s (Last)'=>'%s (Прізвище)','%s (Middle)'=>'%s (По батькові)','%s Empty message.'=>'%s Порожнє повідомлення.','%s Empty subject line.'=>'%s Пуста тема.','%s Field'=>'Поле %s','%s PHP extension'=>'%s розширення PHP' . "\0" . '%s розширення PHP' . "\0" . '%s розширень PHP','%s Preview'=>'Попередній перегляд %s','%s Template Preview'=>'Попередній перегляд шаблону %s','%s addon'=>'Доповнення %s','%s ago'=>'%s тому','%s connection'=>'З\'єднання %s','%s customizable form templates'=>'%s настроюваних шаблонів форм','%s has been enabled for this form. Don\'t forget to save your form!'=>'%s було ввімкнено для цієї форми. Не забудьте зберегти форму!','%s license'=>'ліцензія %s','%s logo'=>'Логотип %s','%s plugin'=>'%s плагін','%s remaining'=>'%s залишилося','%s template'=>'Шаблон %s','%s verification failed, please try again later.'=>'Помилка перевірки %s, повторіть спробу пізніше.','(copy)'=>'(копія)','(empty)'=>'(порожній)','(no title)'=>'(без назви)',', '=>', ','--- Select %s ---'=>'--- Виберіть %s ---','--- Select Address ---'=>'--- Виберіть адресу ---','--- Select Choice ---'=>'--- Виберіть варіант ---','--- Select Email ---'=>'--- Виберіть Email ---','--- Select Field ---'=>'--- Виберіть поле ---','--- Select Form Field ---'=>'--- Виберіть поле форми ---','--- Select Mailing List ---'=>'--- Виберіть список розсилки ---','--- Select Name ---'=>'--- Виберіть ім\'я ---','0 items'=>'0 елементів','0.4'=>'0.4','1 Site'=>'1 сайт','1 hour'=>'1 година','1 tag was successfully deleted.'=>'1 позначку успішно видалено.',11=>'11','15 Days'=>'15 днів','15 minutes'=>'15 хвилин','16:9'=>'16:9','2:3'=>'2:3','3 Sites'=>'3 сайти','30 Days'=>'30 днів','30 household item categories for a marketplace'=>'30 категорій товарів для дому для маркетплейсів','30 minutes'=>'30 хвилин','3:2'=>'3:2','4:5'=>'4:5','5 Sites'=>'5 сайтів','5:4'=>'5:4','7 Days'=>'7 днів','90 Days'=>'90 днів','9:16'=>'9:16','<a href="%1$s" class="wpforms-btn-preview" target="_blank" rel="noopener">Preview Email Template</a>'=>'<a href="%1$s" class="wpforms-btn-preview" target="_blank" rel="noopener">Попередній перегляд шаблону листа</a>','<a href="%s" target="_blank" rel="noopener noreferrer">Read our walk through</a> to learn more and for step-by-step directions.'=>'<a href="%s" target="_blank" rel="noopener noreferrer">Прочитайте нашу документацію</a>, щоб дізнатися більше та отримати покрокові інструкції.','<a href="%s">Go to the full page</a> to view and submit the form.'=>'<a href="%s">Перейдіть на повну сторінку</a>, щоб переглянути та надіслати форму.','<b>Heads up!</b> Don\'t forget to test your form. <a href="%s" target="_blank" rel="noopener noreferrer">Check out our complete guide!</a>'=>'<b>Увага!</b> Не забудьте перевірити свою форму. <a href="%s" target="_blank" rel="noopener noreferrer">Ознайомтеся з нашим повним посібником!</a>','<b>You haven\'t created a form yet.</b><br> What are you waiting for?'=>'<b>Ви ще не створили форму.</b><br> Чого ви чекаєте?','<h4>Add Text and Images to Your Form With Ease</h4> <p>To get started, replace this text with your own.</p>'=>'<h4>Легко додайте текст і зображення до своєї форми</h4> <p>Щоб почати, замініть цей текст на свій власний.</p>','<h4>Images are not cropped or resized.</h4><p>For best results, they should be the same size and 250x250 pixels or smaller.</p>'=>'<h4>Зображення не обрізаються та їх розмір не змінюється. </h4><p>Для оптимального результату вони всі мають бути однакового розміру: 250x250 пікселів або менше.</p>','<p>AJAX form submissions are required when using the Stripe Credit Card field.</p><p>To proceed, please go to <strong>Settings » General » Advanced</strong> and check <strong>Enable AJAX form submission</strong>.</p>'=>'<p>При використанні поля банківської картки Stripe потрібні форми AJAX.</p><p>Щоб продовжити, перейдіть до <strong>Налаштування » Загальне » Додатково</strong> та виберіть <strong>"Увімкнути AJAX надсилання форми"</strong>.</p>','<p>Stripe Payments must be enabled when using the Stripe Credit Card field.</p><p>To proceed, please go to <strong>Payments » Stripe</strong> and check <strong>Enable Stripe payments</strong>.</p>'=>'<p>При використанні поля банківської картки Stripe необхідно увімкнути платежі Stripe.</p><p>Щоб продовжити, перейдіть до <strong>Платежі » Stripe</strong> і позначте пункт <strong>"Увімкнути платежі Stripe"</strong>.</p>','<p>Stripe account connection is required when using the Stripe Credit Card field.</p><p>To proceed, please go to <strong>WPForms Settings » Payments » Stripe</strong> and press <strong>Connect with Stripe</strong> button.</p>'=>'<p>При використанні поля банківської картки Stripe необхідно підключитися до облікового запису Stripe.</p><p>Щоб продовжити, перейдіть до <strong>Налаштування WPForms » Платежі » Stripe</strong> та натисніть кнопку <strong>"Підключити Stripe"</strong>.</p>','<p>Switching test/live modes requires Stripe account reconnection.</p><p>Press the <em>"Connect with Stripe"</em> button after saving the settings to reconnect.</p>'=>'<p>При перемиканні між тестовим/робочим режимом потрібно знову підключити обліковий запис Stripe.</p><p>Для підключення натисніть кнопку <em>"Підключити Stripe"</em> після збереження налаштувань.</p>','<strong>%d forms</strong> selected for Bulk Edit.'=>'<strong>%d форми</strong> вибрано для групового редагування.','<strong>1 form</strong> selected for Bulk Edit.'=>'<strong>1 форма</strong> вибрана для групового редагування.','<strong>AI features were hidden by filter or constant.</strong>'=>'<strong>Функції ШІ були приховані фільтром або константою.</strong>','<strong>Bonus:</strong> WPForms Lite users get <span class="green">50% off regular price</span>, automatically applied at checkout.'=>'<strong>Бонус:</strong> Користувачі WPForms Lite отримують <span class="green">50% знижки від звичайної ціни</span>, яка автоматично застосовується при оформленні замовлення.','<strong>Bonus:</strong> WPForms Lite users get <span>50% off</span> regular price, automatically applied at checkout.'=>'<strong>Бонус:</strong> Користувачі WPForms Lite отримують <span>знижку 50%</span> від звичайної ціни. Знижка застосовується автоматично під час оплати.','<strong>Email converts</strong> - People who buy products marketed through email spend 138% more than those who don\'t receive email offers.'=>'<strong>Конвертація електронних листів</strong> - Люди, які купують товари, що продаються ел. поштою, витрачають на 138% більше, ніж ті, хто не отримує такі пропозиції.','<strong>Email is still #1</strong> - At least 91% of consumers check their email on a daily basis. You get direct access to your subscribers, without having to play by social media\'s rules and algorithms.'=>'<strong>Електронна пошта як і раніше №1</strong> - Принаймні 91% користувачів щодня перевіряють електронну пошту. Ви отримуєте прямий доступ до своїх підписників, без необхідності грати за правилами та алгоритмами соціальних мереж.','<strong>Pay-as-you-go Pricing</strong><br> 3%% fee per-transaction + Stripe fees. <a href="%s" target="_blank">Upgrade to Pro</a> to remove additional fees and unlock powerful features.'=>'<strong>Оплата по мірі використання</strong><br> 3%% комісія за кожну транзакцію + комісія Stripe. <a href="%s" target="_blank">Оновіть до версії Pro</a>, щоб скасувати додаткові збори та розблокувати потужні функції.','<strong>Pay-as-you-go Pricing</strong><br> 3%% fee per-transaction + Stripe fees. <a href="%s">Renew your license</a> to remove additional fees and unlock powerful features.'=>'<strong>Оплата по мірі використання</strong><br> 3%% комісія за кожну транзакцію + комісія Stripe. <a href="%s" target="_blank">Поновіть ліцензію</a>, щоб скасувати додаткові збори та розблокувати потужні функції.','<strong>Pay-as-you-go Pricing</strong><br>3%% fee per-transaction + Stripe fees. <a href="%s">Activate your license</a> to remove additional fees and unlock powerful features.'=>'<strong>Оплата по мірі використання</strong><br> 3%% комісія за кожну транзакцію + комісія Stripe. <a href="%s" target="_blank">Активуйте ліцензію</a>, щоб скасувати додаткові збори та розблокувати потужні функції.','<strong>Payments Cannot Be Processed</strong><br>The currency you have set (%1$s) is not supported by Stripe. Please choose a different currency.'=>'<strong>Платежі не можуть бути оброблені</strong><br>Вказана валюта (%1$s) не підтримується Stripe. Виберіть іншу валюту.','<strong>Please Note:</strong> Support for PHP 7.3 and below will be discontinued soon. After this, if no further action is taken, WPForms functionality will be disabled.'=>'<strong>Зверніть увагу:</strong> Підтримка PHP 7.3 і нижче буде припинена найближчим часом. Після цього, якщо не буде вжито додаткових заходів, функціональність WPForms буде вимкнено.','<strong>What do you think of these choices?</strong> If you’re happy with them, you can insert these choices, or make changes by entering additional prompts.'=>'<strong>Що ви думаєте про ці варіанти?</strong> Якщо вони вас влаштовують, ви можете вставити ці варіанти або внести зміни, ввівши додаткові запити.','<strong>You cannot use modern markup because you’re using the deprecated Credit Card field.</strong> If you’d like to use modern markup, replace your credit card field with a payment gateway like <a href="%s" target="_blank" rel="noopener noreferrer">Stripe</a>.'=>'<strong>Ви не можете використовувати сучасну розмітку, оскільки ви використовуєте застаріле поле «Кредитна картка».</strong> Якщо ви хочете використовувати сучасну розмітку, замініть поле кредитної картки платіжним шлюзом, наприклад <a href="%s" target="_blank" rel="noopener noreferrer">Смуга</a>.','<strong>You own your email list</strong> - Unlike with social media, your list is your property and no one can revoke your access to it.'=>'<strong>Ваш власний перелік електронних адрес</strong> - На відміну від соціальних мереж, ваш список є вашою власністю, і ніхто не може заборонити вам доступ до нього.','<strong>You\'re using WPForms Lite.</strong> To unlock more features consider <a href="%s" target="_blank" rel="noopener noreferrer">upgrading to Pro</a> for 50%% off.'=>'<strong>Ви використовуєте WPForms Lite.</strong> Для доступу до всіх функцій <a href="%s" target="_blank" rel="noopener noreferrer">перейдіть на версію Pro</a> зі знижкою 50%%.','<strong>Your form entries are not being stored in WordPress, and your entry backups are not active.</strong> If there\'s a problem with deliverability, you\'ll lose form entries. We recommend that you enable Entry Backups, especially if you\'re considering <a href="%s" target="_blank" rel="noopener noreferrer" class="wpforms-upgrade-modal">upgrading to WPForms PRO</a>.'=>'<strong>Ваші записи форми не зберігаються в WordPress, а резервні копії записів не активні.</strong> Якщо виникнуть проблеми з доставлення, ви втратите записи форми. Ми рекомендуємо вам увімкнути резервне копіювання записів, особливо якщо ви збираєтеся <a href="%s" target="_blank" rel="noopener noreferrer" class="wpforms-upgrade-modal">оновити до WPForms PRO</a>.','<strong>Your form entries are not being stored locally, but are backed up remotely.</strong> If you <a href="%s" target="_blank" rel="noopener noreferrer" class="wpforms-upgrade-modal">upgrade to WPForms PRO</a>, you can restore your entries and they’ll be available in the WordPress dashboard.'=>'<strong>Ваші записи форми не зберігаються локально, а створюються віддалено.</strong> If you <a href="%s" target="_blank" rel="noopener noreferrer" class="wpforms-upgrade-modal">оновіть до WPForms PRO</a>, ви можете відновити свої записи, і вони будуть доступні на інформаційній панелі WordPress.','<strong>v2 Checkbox reCAPTCHA</strong>: Prompts users to check a box to prove they\'re human.'=>'<strong>v2 Checkbox reCAPTCHA</strong>: Пропонує користувачам поставити прапорець, щоб підтвердити, що вони люди.','<strong>v2 Invisible reCAPTCHA</strong>: Uses advanced technology to detect real users without requiring any input.'=>'<strong>v2 Invisible reCAPTCHA</strong>: Використовує передові технології для виявлення реальних користувачів, не вимагаючи введення даних.','<strong>v3 reCAPTCHA</strong>: Uses a behind-the-scenes scoring system to detect abusive traffic, and lets you decide the minimum passing score. Recommended for advanced use only (or if using Google AMP).'=>'<strong>v3 reCAPTCHA</strong>: Використовує приховану систему підрахунку балів для виявлення зловмисного трафіку та дає змогу визначити мінімальний прохідний бал. Рекомендується тільки для комплексного використання (або при використанні Google AMP).','A CAPTCHA is an anti-spam technique which helps to protect your website from spam and abuse while letting real people pass through with ease.'=>'CAPTCHA — це метод захисту від спаму, який допомагає захистити ваш веб-сайт від спаму та зловживань, дозволяючи реальним людям легко проходити через нього.','A Complete Guide to WPForms Settings'=>'Повний посібник із налаштувань WPForms','A Website or Blog'=>'Веб-сайт або блог','A new and improved Stripe interface is available when you create new forms.'=>'Новий покращений інтерфейс Stripe доступний при створенні нових форм.','A new and improved Stripe interface is available with new Stripe Pro addon.'=>'Новий покращений інтерфейс Stripe доступний з новим доповненням Stripe Pro.','A preview of your CAPTCHA is displayed below. Please view to verify the CAPTCHA settings are correct.'=>'Попередній перегляд вашої CAPTCHA відображається нижче. Переконайтеся, що налаштування CAPTCHA правильні та все працює, як потрібно.','A simple & powerful event calendar plugin for WordPress that comes with all the event management features including payments, scheduling, timezones, ticketing, recurring events, and more.'=>'Простий і потужний плагін календаря подій для WordPress з усіма функціями управління подіями, включаючи платежі, планування, часові пояси, продаж квитків, повторювані події та багато іншого.','AI Calculations Are Here!'=>'Розрахунки ШІ вже тут!','AI Features Enabled'=>'Функції ШІ ввімкнено','AIOSEO'=>'AIOSEO','AIOSEO Pro'=>'AIOSEO Pro','API response: %1$s %2$s'=>'Відповідь API: %1$s %2$s','About Us'=>'Про нас','About WPForms'=>'Про WPForms','Above'=>'Вище','Accept payments using PayPal Commerce, Stripe, Square, PayPal Standard, and Authorize.Net'=>'Приймайте платежі через PayPal Commerce, Stripe, Square, PayPal Standard і Authorize.Net','Accept payments using PayPal Commerce, Stripe, Square, and PayPal Standard'=>'Приймайте платежі через PayPal Commerce, Stripe, Square і PayPal Standard','Accept user-submitted content with the Post Submissions addon'=>'Приймайте вміст, надісланий користувачами, за допомогою доповнення Post Submissions','Acceptance Field'=>'Поле згоди','Access'=>'Доступ','Access Control'=>'Контроль доступу','Access Controls'=>'Контроль доступу','Access controls allows you to manage and customize access to WPForms functionality. You can easily grant or restrict access using the simple built-in controls, or use our official integrations with Members and User Role Editor plugins.'=>'Контроль доступу дозволяє вам налаштовувати доступ до функцій WPForms. Ви можете надавати або обмежувати доступ за допомогою простих вбудованих елементів керування або використовувати нашу офіційну інтеграцію з плагінами Members і User Role Editor.','Access powerful marketing and payment integrations, advanced form fields, and more when you purchase our Plus, Pro, or Elite plans.'=>'Отримайте доступ до ефективних маркетингових і платіжних інтеграцій, розширених полів форм та багато іншого, придбавши наші плани Plus, Pro або Elite.','Access to all Standard, Fancy, and Payment Fields'=>'Доступ до всіх стандартних, складних та платіжних полів','Account Nickname'=>'Псевдонім облікового запису','Action Scheduler library is also used by other plugins, like WP Mail SMTP and WooCommerce, so you might see tasks that are not related to our plugin in the table below.'=>'Бібліотека планувальника дій також використовується іншими плагінами, такими як WP Mail SMTP і WooCommerce, тому в таблиці нижче ви можете побачити завдання, не пов’язані з нашим плагіном.','Activate'=>'Активувати','Activate Now'=>'Активувати зараз','Activate Uncanny Automator'=>'Активувати Uncanny Automator','Activate WP Mail SMTP'=>'Активувати WP Mail SMTP','Activate WPCode'=>'Активувати WPCode','Activated'=>'Активовано','Activating'=>'Активується','Activating...'=>'Активація...','Active'=>'Діючий','Add'=>'Додати','Add Another'=>'Додати інший','Add Choices (one per line)'=>'Додати варіанти (по одному на рядок)','Add Custom Value'=>'Додати власне значення','Add Fields'=>'Додати поля','Add Fields to Your Form'=>'Додавання полів до форми','Add Form'=>'Додати форму','Add Google\'s free anti-spam service and choose between visible or invisible CAPTCHAs.'=>'Додайте безкоштовну службу захисту від спаму від Google і виберіть видиму чи невидиму CAPTCHA.','Add Media'=>'Додати медіафайл','Add New'=>'Додати нове','Add New %s'=>'Додати нове %s','Add New Account'=>'Додати обліковий запис','Add New Choices'=>'Додати нові варіанти','Add New Confirmation'=>'Додати нове підтвердження','Add New Connection'=>'Додати нове з\'єднання','Add New Form'=>'Додати нову форму','Add New Group'=>'Додати нову групу','Add New Notification'=>'Додати нове сповіщення','Add New Plan'=>'Додати новий план','Add Notes / Comments'=>'Додавання нотаток / коментарів','Add a Block'=>'Додати блок','Add advanced form fields and conditional logic, plus offer more payment options, manage entries, and connect to your favorite marketing tools – all when you purchase a premium plan.'=>'Додавайте розширені поля форм та умовну логіку, а також пропонуйте більше варіантів оплати, керуйте записами та підключайтеся до улюблених маркетингових інструментів - все це доступно після придбання преміум-плану.','Add choices for the form field.'=>'Додайте варіанти вибору для поля форми.','Add to Form'=>'Додати до форми','Add your form'=>'Додайте свою форму','Add your new form to any post, page, or sidebar.'=>'Додайте свою нову форму до будь-якого запису, сторінки чи бічної колонки.','Additional Anti-Spam Settings'=>'Додаткові налаштування захисту від спаму','Additional CSS Classes'=>'Додаткові класи CSS','Additional Classes'=>'Додаткові класи','Additional Marketing Integrations'=>'Додаткові маркетингові інтеграції','Additional information'=>'Додаткова інформація','Addon'=>'Додаток','Addon Templates'=>'Шаблони додатків','Addon activated'=>'Додаток активовано','Addon activated.'=>'Додаток активовано.','Addon deactivated.'=>'Додаток деактивовано.','Addon installed & activated.'=>'Додаток встановлено та активовано.','Addon installed.'=>'Доповнення встановлено.','Addons'=>'Додатки','Address'=>'Адреса','Address Autocomplete'=>'Автозаповнення адреси','Address Autocomplete Field'=>'Поле автозаповнення адреси','Address, Phone, Website / URL, Date / Time, Password, File Upload, Layout, Rich Text, Content, HTML, Pagebreaks, Entry Preview, Section Dividers, Ratings, and Hidden Field'=>'Адреса, телефон, веб-сайт/URL, дата/час, пароль, надсилання файлів, розмітка, розширений текст, вміст, HTML, розриви сторінки, перегляд запису, розділювачі розділів, рейтинги та приховане поле','Adds an expandable content area below the description.'=>'Додає область вмісту, що розгортається, під описом.','Advanced'=>'Додатково','Advanced Details'=>'Додаткові відомості','Advanced Fields'=>'Розширені поля','Advanced Form Features'=>'Розширені можливості форм','Advanced date options.'=>'Розширені параметри дати.','Advanced details'=>'Додаткові відомості','Advanced time options.'=>'Розширені параметри часу.','AffiliateWP'=>'AffiliateWP','Afghanistan'=>'Афганістан','After purchasing a license, just <strong>enter your license key on the WPForms Settings page</strong>. This will let your site automatically upgrade to %s! (Don\'t worry, all your forms and settings will be preserved.)'=>'Після придбання ліцензії просто <strong>введіть свій ліцензійний ключ на сторінці налаштувань WPForms</strong>. Це дозволить автоматично оновити ваш сайт до %s! (Не хвилюйтеся, усі ваші форми та налаштування буде збережено.)','After saving these settings, be sure to <a href="%1$s" target="_blank" rel="noopener noreferrer">test a form submission</a>. This lets you see how emails will look, and to ensure that they <a href="%2$s" target="_blank" rel="noopener noreferrer">are delivered successfully</a>.'=>'Після збереження налаштувань обов’язково <a href="%1$s" target="_blank" rel="noopener noreferrer">перевірте відправлення форми</a>. Це дозволяє побачити, як виглядатимуть листи, і переконатися, що вони <a href="%2$s" target="_blank" rel="noopener noreferrer">будуть успішно доставлені</a>.','After upgrading, your license key will remain the same.<br>You may need to do a quick refresh to unlock your new addons. In your WordPress admin, go to <strong>WPForms &raquo; Settings</strong>. If you don\'t see your updated plan, click <em>refresh</em>.'=>'Після зміни тарифного плану ваш ліцензійний ключ залишиться незмінним.<br>Можливо, вам доведеться зробити швидке оновлення, щоб розблокувати нові доповнення. В обліковому записі адміністратора WordPress відкрийте <strong>WPForms &raquo; Налаштування</strong>. Якщо новий план не відображається, натисніть <em>"Оновити"</em>.','Agree'=>'Згоден','Agreement'=>'Угода','Akismet'=>'Akismet','Alabama'=>'Алабама','Alaska'=>'Аляска','Albania'=>'Албанія','Algeria'=>'Алжир','All'=>'Всі','All %s'=>'Всі %s','All Addons Included'=>'Доступні всі доповнення','All Advanced Features'=>'Всі розширені можливості','All Form Templates including Bonus %s pre-made form templates'=>'Усі шаблони форм, включно з готовими шаблонами бонусних форм (%s)','All Forms'=>'Всі форми','All Logs'=>'Усі журнали','All Marketing Integrations'=>'Всі маркетингові інтеграції','All Tags'=>'Всі позначки','All Templates'=>'Всі шаблони','All forms and settings will be unrecoverable.'=>'Всі форми та налаштування буде неможливо відновити.','All forms, entries, and uploaded files will be unrecoverable.'=>'Усі форми, записи та завантажені файли неможливо буде відновити.','Allow Usage Tracking'=>'Дозволити відстеження даних про використання','Allow users to select multiple choices in this field.'=>'Дозволити користувачам вибирати кілька варіантів у цьому полі.','Allow your customer to pay recurringly via the form.'=>'Дозвольте клієнтам проводити регулярні платежі через форму.','Allow your customers to one-time pay via the form.'=>'Дозвольте клієнтам проводити одноразові платежі через форму.','Allow your users to easily log in to your site with their username and password.'=>'Дозвольте користувачам легко входити на ваш сайт, використовуючи своє ім\'я користувача та пароль.','Allow your users to easily reset their password.'=>'Дайте користувачам можливість легко скидати паролі.','Allowlist'=>'Список дозволених','Allowlist / Denylist'=>'Дозволені / Заборонені','Almost Done'=>'Майже готово','Almost done!'=>'Майже готово!','Almost done! Would you like to save and refresh the form builder?'=>'Майже готово! Бажаєте зберегти та оновити конструктор форм?','Already purchased?'=>'Вже придбано?','Already purchased? Simply enter your license key below to enable WPForms PRO!'=>'Уже придбали ключ? Тоді просто вставте його нижче, щоб активувати WPForms PRO!','Also Available'=>'Також в наявності','Also used for other fields like Multiple Choice, Checkboxes, Rating, and NPS Survey.'=>'Також використовується для інших полів, таких як множинний вибір, прапорці, рейтинг і опитування NPS.','Alternately, try using a From Address that matches your website domain (admin@%1$s).'=>'Крім того, спробуйте використати адресу "Від", яка відповідає домену вашого веб-сайту (admin@%1$s).','American Samoa'=>'Американське Самоа','Amount can\'t be less than the required minimum.'=>'Сума не може бути меншою за необхідний мінімум.','Amount can\'t be negative'=>'Сума не може бути від’ємною','Amount entered is less than the required minimum.'=>'Введена сума менша за необхідний мінімум.','Amount mismatch'=>'Невідповідність суми','An empty form was submitted.'=>'Було надіслано порожню форму.','An error occurred while generating choices.'=>'Під час створення варіантів сталася помилка.','An error occurred.'=>'Сталася помилка.','Analyzing <span class="form-current">1</span> of <span class="form-total">0</span> forms from %s.'=>'Аналіз <span class="form-current">1</span> із <span class="form-total">0</span> форм від %s.','And'=>'І','Andorra'=>'Андорра','Angola'=>'Ангола','Anguilla'=>'Ангілья','Antarctica'=>'Антарктида','Anti-spam Honeypot V2 verification was failed, please try again later.'=>'Помилка перевірки антиспаму Honeypot V2, повторіть спробу пізніше.','Anti-spam verification failed, please try again later.'=>'Помилка перевірки захисту від спаму, повторіть спробу пізніше.','Antigua and Barbuda'=>'Антигуа і Барбуда','Antispam filter did not allow your data to pass through.'=>'Антиспам-фільтр не пропустив ваші дані.','Antispam token is invalid.'=>'Токен захисту від спаму недійсний.','Any payment field'=>'Будь-який поле оплати','Appearance'=>'Зовнішній вигляд','Apply'=>'Застосувати','April'=>'Квітень','Are you sure you want to cancel this subscription?'=>'Ви впевнені, що хочете скасувати цю підписку?','Are you sure you want to clear the AI chat history and start over?'=>'Ви впевнені, що хочете очистити історію чату ШІ та почати спочатку?','Are you sure you want to delete %s entries? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете видалити записи в кількості %s? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure you want to delete ALL entries? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете видалити ВСІ записи? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure you want to delete ALL the forms in the trash and all their entries?'=>'Ви впевнені, що хочете видалити ВСІ форми з кошика та всі їхні записи?','Are you sure you want to delete the %1$s theme?'=>'Ви впевнені, що хочете видалити тему %1$s?','Are you sure you want to delete the selected forms and all their entries?'=>'Ви впевнені, що хочете видалити вибрані форми та всі їхні записи?','Are you sure you want to delete this choice?'=>'Ви впевнені, що хочете видалити цей варіант?','Are you sure you want to delete this confirmation?'=>'Ви впевнені, що хочете видалити це підтвердження?','Are you sure you want to delete this connection?'=>'Ви впевнені, що хочете видалити цей підключення?','Are you sure you want to delete this entry? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете видалити цей запис? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure you want to delete this field?'=>'Ви впевнені, що хочете видалити це поле?','Are you sure you want to delete this form and all its entries?'=>'Ви впевнені, що хочете видалити цю форму та всі її записи?','Are you sure you want to delete this form template? This cannot be undone.'=>'Ви впевнені, що хочете видалити цей шаблон форми? Це не можна скасувати.','Are you sure you want to delete this note?'=>'Ви впевнені, що хочете видалити цю нотатку?','Are you sure you want to delete this notification?'=>'Ви впевнені, що хочете видалити це сповіщення?','Are you sure you want to delete this payment and all its information (details, notes, etc.)?'=>'Ви впевнені, що хочете видалити цей платіж і всю інформацію про нього (деталі, нотатки тощо)?','Are you sure you want to delete this template and all its entries?'=>'Ви впевнені, що хочете видалити цей шаблон і всі його записи?','Are you sure you want to disable %s for this form?'=>'Ви впевнені, що хочете вимкнути %s для цієї форми?','Are you sure you want to disable conditional logic? This will remove the rules for this field or setting.'=>'Ви впевнені, що хочете відключити умовну логіку? Ця дія видалить усі правила для цього поля або налаштування.','Are you sure you want to duplicate this field?'=>'Ви впевнені, що хочете продублювати це поле?','Are you sure you want to duplicate this form?'=>'Ви впевнені, що хочете продублювати цю форму?','Are you sure you want to duplicate this template?'=>'Ви впевнені, що хочете продублювати цей шаблон?','Are you sure you want to leave? You have unsaved changes'=>'Ви впевнені, що хочете піти? У вас є незбережені зміни','Are you sure you want to refund this payment?'=>'Ви впевнені, що хочете повернути цей платіж?','Are you sure you want to trash %s entries? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете перемістити в кошик записи в кількості %s? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure you want to trash ALL entries? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете видалити ВСІ записи? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure you want to trash this entry? This will also remove all associated files, notes, and logs.'=>'Ви впевнені, що хочете видалити цей запис? Це також призведе до видалення всіх пов\'язаних файлів, нотаток і журналів.','Are you sure?'=>'Ви впевнені?','Are you wondering which form fields you have access to in WPForms and what each field does? WPForms has lots of field types to make creating and filling out forms easy. In this tutorial, we’ll cover all of the fields available in WPForms.'=>'Вам цікаво, до яких полів у вас є доступ у WPForms і що робить кожне поле? У WPForms багато типів полів, щоб спростити створення та заповнення форм. У цьому посібнику ми розглянемо всі поля, доступні в WPForms.','Are your forms converting fewer visitors than you hoped? Often, visitors quit forms partway through. That can prevent you from getting all the leads you deserve to capture. With our Form Abandonment addon, you can capture partial entries even if your visitor didn’t hit Submit! From there, it’s easy to follow up with leads and turn them into loyal customers.'=>'Ваші форми конвертують менше відвідувачів, ніж ви сподівалися? Часто відвідувачі залишають форми на півчасі. Це може перешкодити вам отримати всі потенційні клієнти, які ви заслуговуєте на захоплення. За допомогою нашого аддона для відмови від форми ви можете отримувати часткові записи, навіть якщо ваш відвідувач не натиснув «Надіслати»! Звідси легко зв’язатися з потенційними клієнтами та перетворити їх на лояльних клієнтів.','Argentina'=>'Аргентина','Arizona'=>'Арізона','Arkansas'=>'Арканзас','Armenia'=>'Вірменія','Aruba'=>'Аруба','As a business owner, time is my most valuable asset. WPForms allow me to create smart online forms with just a few clicks. With their pre-built form templates and the drag & drop builder, I can create a new form that works in less than 2 minutes without writing a single line of code. Well worth the investment.'=>'Для мене, як власника бізнесу, час - найцінніший актив. WPForms дає мені змогу створювати розумні онлайн-форми всього кількома натисканнями миші. За допомогою попередньо створених шаблонів форм і механізму перетягування елементів конструктора я можу створити нову форму менш ніж за 2 хвилини, не написавши жодного рядка коду. Це виправдовує вкладені інвестиції.','As a valued WPForms Lite user you receive <strong>50% off</strong>, automatically applied at checkout!'=>'Як цінний користувач WPForms Lite, ви отримаєте <strong>знижку 50%</strong>. Знижка застосується автоматично під час оформлення замовлення!','Ask a question or search the docs...'=>'Задайте питання або пошукайте в документації...','Ask custom questions or require your visitor to answer a random math puzzle.'=>'Ставте спеціальні запитання або вимагайте від відвідувача відповіді на випадкову математичну головоломку.','Ask visitors a question and display the results after they provide an answer.'=>'Поставити відвідувачам запитання та після відповіді показати їм результати.','At least one of the emails in your list contained an error and has been removed.'=>'Принаймні одна з адрес електронної пошти у вашому списку містила помилку та її було видалено.','August'=>'Серпень','Australia'=>'Австралія','Australian Dollar'=>'Австралійський долар','Austria'=>'Австрія','Authentication with Stripe API failed.'=>'Помилка автентифікації за допомогою API Stripe.','Author'=>'Автор','Author Email'=>'Електронна пошта автора','Author ID'=>'ID автора','Author Name'=>'Ім’я автора','Authorization Code'=>'Код авторизації','Authorize.Net'=>'Authorize.Net','Authorize.net'=>'Authorize.net','Auto'=>'Авто','Automated tests that help to prevent bots from submitting your forms.'=>'Автоматичні тести, які допомагають запобігти надсиланню ваших форм роботами.','Automatically scroll to the confirmation message'=>'Автоматичний перехід до повідомлення з підтвердженням','Available Fields'=>'Доступні поля','Available Form Fields'=>'Доступні поля форми','Available Forms'=>'Доступні форми','Available Templates'=>'Доступні шаблони','Awesome! If you decide to upgrade to WPForms Pro, you can restore your entries and will have instant access to reports.'=>'Чудово! Якщо ви вирішите перейти на WPForms Pro, ви можете відновити свої записи та матимете миттєвий доступ до звітів.','Azerbaijan'=>'Азербайджан','Back to All Entries'=>'Повернутися до записів','Back to All Forms'=>'Повернутися до всіх форм','Back to All Payments'=>'Назад до всіх платежів','Background'=>'Фон','Background Color'=>'Колір фону','Background Styles'=>'Стилі фону','Backup & Restore'=>'Резервне копіювання та відновлення','Backup and Restore.'=>'Резервне копіювання та відновлення.','Backups are completely free, 100%% secure, and you can turn them on in a few clicks! <a href="%1$s" target="_blank" rel="noopener noreferrer">Enable entry backups now.</a>'=>'Резервне копіювання абсолютно безкоштовне, 100%% безпечне, і ви можете ввімкнути його кількома кліками! <a href="%1$s" target="_blank" rel="noopener noreferrer">Увімкнути резервне копіювання записів зараз.</a>','Bad response'=>'Погана відповідь','Bahamas'=>'Багамські острови','Bahrain'=>'Бахрейн','Bangladesh'=>'Б